/// Read-only ayah data (generated by tool/build_ayah_assets.py; formats in
/// specs/002-ayah-actions-sharing/contracts/assets.md, entities in data-model.md).
library;

/// One tafsir passage covering the consecutive ayahs [from]..[to] of one surah. [text] is plain text,
/// paragraphs separated by a line break.
class TafsirEntry {
  const TafsirEntry({required this.from, required this.to, required this.text});

  factory TafsirEntry.fromJson(Map<String, dynamic> json) => TafsirEntry(
    from: json['from'] as int,
    to: json['to'] as int,
    text: json['text'] as String,
  );

  final int from;
  final int to;
  final String text;

  bool contains(int ayah) => from <= ayah && ayah <= to;

  /// «6–7» (an en dash, digits 0-9), or just the number when the entry covers a single ayah.
  String get covers => from == to ? '$from' : '$from–$to';
}

/// The tafsir shown for an ayah. [inherited] is true for the ayahs the source has no commentary of their
/// own for: [entry] is then the nearest earlier entry of the same surah (spec FR-009a).
class TafsirResult {
  const TafsirResult(this.entry, {required this.inherited});

  final TafsirEntry entry;
  final bool inherited;
}

/// A difficult word (or short phrase) of an ayah with its meaning, from the source book [book].
class GharibEntry {
  const GharibEntry({
    required this.word,
    required this.meaning,
    required this.book,
  });

  factory GharibEntry.fromJson(Map<String, dynamic> json) => GharibEntry(
    word: json['w'] as String,
    meaning: json['m'] as String,
    book: json['b'] as int,
  );

  final String word;
  final String meaning;
  final int book;
}

/// Where a bundled text comes from: shown as a label next to it and listed on the About screen.
class Source {
  const Source({
    required this.id,
    required this.kind,
    required this.title,
    required this.provider,
    required this.link,
    required this.version,
    this.author,
  });

  factory Source.fromJson(Map<String, dynamic> json) => Source(
    id: '${json['id']}',
    kind: json['kind'] as String,
    title: json['title'] as String,
    author: json['author'] as String?,
    provider: json['provider'] as String,
    link: json['link'] as String,
    version: json['version'] as String,
  );

  /// `qul-312`, `qul-24`, `tanzil-en-sahih`, or a gharib book id such as `327`.
  final String id;

  /// `text`, `tafsir`, `translation` or `gharib`.
  final String kind;
  final String title;
  final String? author;
  final String provider;
  final String link;
  final String version;
}
